const name = "Amber";   // запечатали — переназначить нельзя
// name = "Other";      // TypeError: Assignment to constant variable

// Но const НЕ делает значение неизменяемым!
const scores = [10, 20]; // коробка запечатана, но содержимое — живое
scores.push(30);         // можно: добавили внутрь массива
// scores = [1, 2];      // нельзя: это попытка выбросить старый массив

// var игнорирует блоки {}:
if (true) {
  var leaky = "вытек из блока";
}
console.log(leaky);  // 'вытек из блока' — var вылез из if!

// let остаётся внутри блока:
if (true) {
  let blockScoped = "живу в блоке";
}
// console.log(blockScoped);  // ReferenceError — не видно снаружи

